svg.script:
(function(){
  const svg=document.querySelector('svg');
  const meta=JSON.parse(document.getElementById('pbn-meta').textContent);
  const cols=4, cellW=205, cellH=40, startX=40, startY=950;
  const rows=Math.ceil(meta.palette.length/cols), buttonY=startY+rows*cellH+12;
  const legendHeight=(buttonY-900)+56, viewHeight=900+legendHeight+15;
  svg.setAttribute('viewBox',`0 0 900 ${viewHeight}`);
  svg.setAttribute('height',String(viewHeight));
  const labels=document.getElementById('number-labels');
  const legend=document.getElementById('legend');
  legend.setAttribute('display','inline');
  const NS='http://www.w3.org/2000/svg';
  const make=(tag,at,text)=>{const e=document.createElementNS(NS,tag);Object.entries(at||{}).forEach(([k,v])=>e.setAttribute(k,v));if(text!=null)e.textContent=text;return e};
  let numbersVisible=true;
  document.querySelectorAll('.region').forEach((el)=>{
    const n=Number(el.getAttribute('data-color'));
    const color=meta.palette[n-1].hex;
    el.dataset.suggested=color;
    el.setAttribute('fill','#fffdf8');
    el.style.cursor='pointer';
    let b; try{b=el.getBBox()}catch(_){return}
    if(b.width>=28 && b.height>=20){
      const t=make('text',{x:(b.x+b.width/2).toFixed(1),y:(b.y+b.height/2+5).toFixed(1),'text-anchor':'middle','font-family':'Arial,sans-serif','font-size':Math.max(11,Math.min(24,Math.sqrt(b.width*b.height)/7)).toFixed(0),'font-weight':'800',fill:'#51463d','pointer-events':'none','data-for':n},String(n));
      labels.appendChild(t); el.dataset.labelIndex=labels.children.length-1;
    }
    el.addEventListener('click',(ev)=>{
      if(ev.shiftKey){el.setAttribute('fill','#fffdf8');}else{el.setAttribute('fill',color)}
      const idx=Number(el.dataset.labelIndex); if(Number.isFinite(idx)&&labels.children[idx]) labels.children[idx].setAttribute('display',ev.shiftKey&&numbersVisible?'inline':'none');
    });
  });
  meta.palette.forEach((p,i)=>{
    const col=i%cols,row=Math.floor(i/cols),x=startX+col*cellW,y=startY+row*cellH;
    legend.appendChild(make('rect',{x,y,width:34,height:28,rx:5,fill:p.hex,stroke:'#2d2930','stroke-width':2}));
    legend.appendChild(make('text',{x:x+43,y:y+20,'font-family':'Arial,sans-serif','font-size':15,'font-weight':700,fill:'#2d2930'},`${i+1}. ${p.name}`));
  });
  const btn=(x,label,fn)=>{const g=make('g',{cursor:'pointer'});g.appendChild(make('rect',{x,y:buttonY,width:160,height:38,rx:12,fill:'#fffaf1',stroke:'#6f5a43','stroke-width':2}));g.appendChild(make('text',{x:x+80,y:buttonY+25,'text-anchor':'middle','font-family':'Arial,sans-serif','font-size':16,'font-weight':800,fill:'#3d342c'},label));g.addEventListener('click',fn);legend.appendChild(g)};
  const bg=document.getElementById('legend-bg');if(bg)bg.setAttribute('height',String(legendHeight));
  btn(160,'Fill all',()=>document.querySelectorAll('.region').forEach(el=>{el.setAttribute('fill',el.dataset.suggested); const idx=Number(el.dataset.labelIndex);if(Number.isFinite(idx)&&labels.children[idx])labels.children[idx].setAttribute('display','none')}));
  btn(370,'Reset',()=>document.querySelectorAll('.region').forEach(el=>{el.setAttribute('fill','#fffdf8');const idx=Number(el.dataset.labelIndex);if(Number.isFinite(idx)&&labels.children[idx])labels.children[idx].setAttribute('display',numbersVisible?'inline':'none')}));
  btn(580,'Toggle numbers',()=>{numbersVisible=!numbersVisible;labels.setAttribute('display',numbersVisible?'inline':'none')});
})();
